/*
 * demo_status_table.c -- LMDB-backed net-snmp table handlers for the demo_status_table group.
 *
 * GENERATED by mib2c using mib2c/mib2c.dbtable.conf.
 * DO NOT EDIT BY HAND -- regenerate with scripts/gen_mib2c.sh.
 *
 * Rows are not held in memory: each request enumerates them from the LMDB
 * key space (table_rows.h) and every cell is read on MODE_GET / written on
 * MODE_SET_ACTION through storage_lmdb.h (config_env / cache_env, see
 * subagent_env.h). The backend is chosen per column by storage_mode.h, so a
 * single row can straddle both environments.
 */
#include <net-snmp/net-snmp-config.h>
#include <net-snmp/net-snmp-includes.h>
#include <net-snmp/agent/net-snmp-agent-includes.h>
#include <stdlib.h>
#include <string.h>

#include "demo_status_table.h"
#include "storage_lmdb.h"
#include "storage_mode.h"
#include "subagent_env.h"
#include "table_oid.h"
#include "table_rows.h"

/* =================================================================== */
/* sensorTable (3 accessible column(s))                                    */
/* =================================================================== */

#define COLUMN_SENSORNAME 2
#define COLUMN_SENSORTEMPMILLIC 3
#define COLUMN_SENSORSAMPLECOUNT 4

/* sensorName is read-only: always cache.lmdb, no compile time switch. */
#define TABLE_ENV_sensorName cache_env
/* sensorTempMilliC is read-only: always cache.lmdb, no compile time switch. */
#define TABLE_ENV_sensorTempMilliC cache_env
/* sensorSampleCount is read-only: always cache.lmdb, no compile time switch. */
#define TABLE_ENV_sensorSampleCount cache_env

/* Number of accessible columns, i.e. of key prefixes a row can appear under. */
#define sensorTable_NCOLUMNS 3

/* Loop state for one walk over sensorTable's rows. */
struct sensorTable_loop {
    table_rowset_t *rows;
    size_t          next;
};

/*
 * Data context for a matched row of sensorTable.
 *
 * It carries no row data on purpose. net-snmp's table iterator hands the
 * same data context pointer to every request that matched the same row and
 * then releases it once per request, so a per-row allocation here would be a
 * double free the moment a manager set two columns of one row in a single
 * PDU. The address of this object only means "the row exists"; the instance
 * itself is recovered from the request's index varbinds with
 * table_instance_from_indexes() (see include/table_oid.h), which is also
 * what keeps MODE_SET_RESERVE2 and later working -- only MODE_SET_RESERVE1
 * walks the rows.
 */
static char sensorTable_row_present;

/* Last reported count of skipped (malformed) cell keys, see below. */
static size_t sensorTable_last_skipped;

static Netsnmp_Node_Handler        handle_sensorTable;
static Netsnmp_First_Data_Point    sensorTable_get_first_data_point;
static Netsnmp_Next_Data_Point     sensorTable_get_next_data_point;
static Netsnmp_Free_Loop_Context   sensorTable_free_loop_context;

/*
 * The (environment, column) pairs a row of sensorTable can appear under. Filled at
 * call time rather than statically initialised because config_env/cache_env
 * are runtime handles.
 */
static void
sensorTable_column_refs(table_column_ref_t refs[sensorTable_NCOLUMNS])
{
    refs[0].env = TABLE_ENV_sensorName;
    refs[0].column = "sensorName";
    refs[1].env = TABLE_ENV_sensorTempMilliC;
    refs[1].column = "sensorTempMilliC";
    refs[2].env = TABLE_ENV_sensorSampleCount;
    refs[2].column = "sensorSampleCount";
}

static netsnmp_variable_list *
sensorTable_get_first_data_point(void **loop_context, void **data_context,
                          netsnmp_variable_list *put_index_data,
                          netsnmp_iterator_info *iinfo)
{
    table_column_ref_t refs[sensorTable_NCOLUMNS];
    struct sensorTable_loop *loop;
    table_rowset_t *rows = NULL;
    storage_rc_t rc;

    /*
     * With NETSNMP_ITERATOR_FLAG_SORTED the iterator passes a hint of its own
     * in *loop_context. This function ignores it and installs its own loop
     * state -- but it must install something on every path, including the
     * failure paths below: whatever *loop_context holds at the end of the
     * iteration is handed to sensorTable_free_loop_context().
     */
    *loop_context = NULL;

    sensorTable_column_refs(refs);

    rc = table_rowset_load(refs, sensorTable_NCOLUMNS, &rows);
    if (rc != STORAGE_OK) {
        snmp_log(LOG_ERR, "sensorTable: row enumeration failed: %s\n",
                  storage_strerror(rc));
        return NULL;
    }
    /*
     * Rows are enumerated once per request, so an unconditional warning here
     * would repeat for every varbind of every walk. Report only when the
     * count changes, which still surfaces a writer that starts (or stops)
     * producing malformed keys without burying the log.
     */
    if (table_rowset_skipped(rows) != sensorTable_last_skipped) {
        sensorTable_last_skipped = table_rowset_skipped(rows);
        if (sensorTable_last_skipped > 0) {
            snmp_log(LOG_WARNING,
                      "sensorTable: ignoring %lu cell key(s) whose row instance is not "
                      "canonical dotted decimal\n",
                      (unsigned long)sensorTable_last_skipped);
        }
    }

    loop = calloc(1, sizeof(*loop));
    if (loop == NULL) {
        table_rowset_free(rows);
        snmp_log(LOG_ERR, "sensorTable: out of memory allocating loop context\n");
        return NULL;
    }
    loop->rows = rows;
    loop->next = 0;
    *loop_context = loop;

    return sensorTable_get_next_data_point(loop_context, data_context,
                                    put_index_data, iinfo);
}

static netsnmp_variable_list *
sensorTable_get_next_data_point(void **loop_context, void **data_context,
                         netsnmp_variable_list *put_index_data,
                         netsnmp_iterator_info *iinfo)
{
    struct sensorTable_loop *loop = (struct sensorTable_loop *)*loop_context;

    (void)iinfo;

    if (loop == NULL) {
        return NULL;
    }

    while (loop->next < table_rowset_count(loop->rows)) {
        const table_instance_t *inst = table_rowset_at(loop->rows, loop->next++);

        /*
         * put_index_data carries this table's index syntax, so filling it is
         * also the validation step: a key whose instance does not decode into
         * exactly these indexes is not a row of this table and is skipped
         * rather than reported as one.
         */
        if (table_instance_to_indexes(inst, put_index_data) != 0) {
            char rejected[STORAGE_KEY_MAX + 1];

            if (table_instance_format(inst, rejected, sizeof(rejected))
                    != STORAGE_OK) {
                rejected[0] = '\0';
            }
            snmp_log(LOG_WARNING,
                      "sensorTable: instance '%s' does not match the table's index "
                      "syntax, skipping the row\n", rejected);
            continue;
        }

        *data_context = &sensorTable_row_present;

        return put_index_data;
    }

    return NULL;
}

static void
sensorTable_free_loop_context(void *context, netsnmp_iterator_info *iinfo)
{
    struct sensorTable_loop *loop = (struct sensorTable_loop *)context;

    (void)iinfo;

    if (loop == NULL) {
        return;
    }
    table_rowset_free(loop->rows);
    free(loop);
}

/** Registers the sensorTable table with the master agent. */
static void
init_table_sensorTable(void)
{
    static const oid sensorTable_oid[] = { 1,3,6,1,4,1,99999,2,5 };
    netsnmp_handler_registration *reg;
    netsnmp_table_registration_info *table_info;
    netsnmp_iterator_info *iinfo;

    DEBUGMSGTL(("demo_status_table", "Registering table sensorTable\n"));

    reg = netsnmp_create_handler_registration(
              "sensorTable", handle_sensorTable, sensorTable_oid, OID_LENGTH(sensorTable_oid),
              HANDLER_CAN_RONLY);
    if (reg == NULL) {
        snmp_log(LOG_ERR, "sensorTable: handler registration allocation failed\n");
        return;
    }

    table_info = SNMP_MALLOC_TYPEDEF(netsnmp_table_registration_info);
    iinfo = SNMP_MALLOC_TYPEDEF(netsnmp_iterator_info);
    if (table_info == NULL || iinfo == NULL) {
        snmp_log(LOG_ERR, "sensorTable: out of memory registering the table\n");
        SNMP_FREE(table_info);
        SNMP_FREE(iinfo);
        netsnmp_handler_registration_free(reg);
        return;
    }

    netsnmp_table_helper_add_indexes(table_info,
                                      ASN_UNSIGNED, /* index: sensorIndex */
                                      0);
    table_info->min_column = COLUMN_SENSORNAME;
    table_info->max_column = COLUMN_SENSORSAMPLECOUNT;

    iinfo->get_first_data_point     = sensorTable_get_first_data_point;
    iinfo->get_next_data_point      = sensorTable_get_next_data_point;
    iinfo->free_loop_context_at_end = sensorTable_free_loop_context;
    /* No free_data_context: a matched row's context is the static sentinel
     * above, not an allocation (see its comment). */
    iinfo->table_reginfo            = table_info;
    /* table_rowset_load() returns rows already in OID order, which lets the
     * iterator stop a GETNEXT at the first row past the requested one. */
    iinfo->flags                   |= NETSNMP_ITERATOR_FLAG_SORTED;

    if (netsnmp_register_table_iterator(reg, iinfo) != SNMPERR_SUCCESS) {
        snmp_log(LOG_ERR, "sensorTable: netsnmp_register_table_iterator failed\n");
    }
}

/** Handles requests for the sensorTable table. */
static int
handle_sensorTable(netsnmp_mib_handler *handler,
          netsnmp_handler_registration *reginfo,
          netsnmp_agent_request_info *reqinfo,
          netsnmp_request_info *requests)
{
    netsnmp_request_info *request;

    (void)handler;
    (void)reginfo;

    switch (reqinfo->mode) {

    case MODE_GET:
        for (request = requests; request != NULL; request = request->next) {
            netsnmp_table_request_info *table_info =
                netsnmp_extract_table_info(request);
            table_instance_t row;
            const table_instance_t *inst = &row;
            char key[STORAGE_KEY_MAX + 1];

            if (table_info == NULL) {
                netsnmp_set_request_error(reqinfo, request, SNMP_ERR_GENERR);
                continue;
            }
            if (netsnmp_extract_iterator_context(request) == NULL) {
                netsnmp_set_request_error(reqinfo, request, SNMP_NOSUCHINSTANCE);
                continue;
            }
            if (table_instance_from_indexes(table_info, &row) != 0) {
                netsnmp_set_request_error(reqinfo, request, SNMP_ERR_GENERR);
                continue;
            }

            switch (table_info->colnum) {
            case COLUMN_SENSORNAME:
                {
                    unsigned char buf[32];
                    size_t len = sizeof(buf);
                    storage_rc_t rc;

                    if (table_cell_key("sensorName", inst, key, sizeof(key)) != STORAGE_OK) {
                        netsnmp_set_request_error(reqinfo, request, SNMP_ERR_GENERR);
                        break;
                    }
                    rc = storage_get_bytes(TABLE_ENV_sensorName, key, buf, &len);
                    if (rc == STORAGE_ERR_NOTFOUND) {
                        /* A row can exist while one of its cells does not;
                         * report the hole rather than inventing a value. */
                        netsnmp_set_request_error(reqinfo, request,
                                                   SNMP_NOSUCHINSTANCE);
                        break;
                    }
                    if (rc != STORAGE_OK) {
                        snmp_log(LOG_ERR, "%s: storage_get_bytes failed: %s\n",
                                  key, storage_strerror(rc));
                        netsnmp_set_request_error(reqinfo, request,
                                                   SNMP_ERR_GENERR);
                        break;
                    }
                    snmp_set_var_typed_value(request->requestvb, ASN_OCTET_STR,
                                              buf, len);
                }
                break;

            case COLUMN_SENSORTEMPMILLIC:
                {
                    int32_t val;
                    storage_rc_t rc;

                    if (table_cell_key("sensorTempMilliC", inst, key, sizeof(key)) != STORAGE_OK) {
                        netsnmp_set_request_error(reqinfo, request, SNMP_ERR_GENERR);
                        break;
                    }
                    rc = storage_get_int(TABLE_ENV_sensorTempMilliC, key, &val);
                    if (rc == STORAGE_ERR_NOTFOUND) {
                        netsnmp_set_request_error(reqinfo, request,
                                                   SNMP_NOSUCHINSTANCE);
                        break;
                    }
                    if (rc != STORAGE_OK) {
                        snmp_log(LOG_ERR, "%s: storage_get_int failed: %s\n",
                                  key, storage_strerror(rc));
                        netsnmp_set_request_error(reqinfo, request,
                                                   SNMP_ERR_GENERR);
                        break;
                    }
                    snmp_set_var_typed_integer(request->requestvb, ASN_INTEGER,
                                                (long)val);
                }
                break;

            case COLUMN_SENSORSAMPLECOUNT:
                {
                    uint32_t val;
                    storage_rc_t rc;

                    if (table_cell_key("sensorSampleCount", inst, key, sizeof(key)) != STORAGE_OK) {
                        netsnmp_set_request_error(reqinfo, request, SNMP_ERR_GENERR);
                        break;
                    }
                    rc = storage_get_uint(TABLE_ENV_sensorSampleCount, key, &val);
                    if (rc == STORAGE_ERR_NOTFOUND) {
                        netsnmp_set_request_error(reqinfo, request,
                                                   SNMP_NOSUCHINSTANCE);
                        break;
                    }
                    if (rc != STORAGE_OK) {
                        snmp_log(LOG_ERR, "%s: storage_get_uint failed: %s\n",
                                  key, storage_strerror(rc));
                        netsnmp_set_request_error(reqinfo, request,
                                                   SNMP_ERR_GENERR);
                        break;
                    }
                    snmp_set_var_typed_integer(request->requestvb, ASN_COUNTER,
                                                (long)val);
                }
                break;

            default:
                netsnmp_set_request_error(reqinfo, request, SNMP_NOSUCHOBJECT);
                break;
            }
        }
        break;


    default:
        snmp_log(LOG_ERR, "unknown mode (%d) in handle_sensorTable\n", reqinfo->mode);
        return SNMP_ERR_GENERR;
    }

    return SNMP_ERR_NOERROR;
}

/** Registers every demo_status_table table with the master agent. */
void
init_demo_status_table(void)
{
    DEBUGMSGTL(("demo_status_table", "Initializing\n"));

    init_table_sensorTable();
}
